 public static bool HostRunning(){Mutex m;if(Mutex.TryOpenExisting("Local\\LifeAC-Lighting-Host",out m)){m.Dispose();return true;}return false;}
 public static string Sha(Stream stream){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 public static bool VerifyPayload(){using(var p=Resource("LifeAC.Payload"))return Sha(p)==ReadResource("LifeAC.PayloadHash");}
 static bool Within(string file,string folder){return Path.GetFullPath(file).StartsWith(Path.GetFullPath(folder).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase);}
 public static bool IsHostInstallation(){try{var role=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(Data,"role.json")))["role"];if(role=="controller")return false;if(role=="primary"||role=="backup")return true;}catch{}try{var d=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(Data,"install.json")));return !d.ContainsKey("role")||d["role"]=="host";}catch{return false;}}
 public static bool ShouldInstall(string rel,bool host){if(host)return true;rel=rel.Replace('/','\\');foreach(string prefix in new[]{"runtime\\","bin\\","src\\","inputs\\"})if(rel.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))return false;return true;}
 public static string Install(Stream payload,string version,Action<string> status,bool? hostRole=null){bool installHost=hostRole??IsHostInstallation();
  if(HostRunning())throw new InvalidOperationException("Close LifeAC Lighting using its tray menu before installing or updating. Lights will not be interrupted by this updater.");
  System.Version parsed;if(!System.Version.TryParse(version,out parsed))throw new InvalidDataException("Invalid version");Directory.CreateDirectory(Root);Directory.CreateDirectory(Data);
  string stage=Path.Combine(Root,"staging-"+Guid.NewGuid().ToString("N")),target=Path.Combine(Root,"releases",version+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(stage);
  try{
   status("Extracting LifeAC Lighting "+version+"…");long total=0;using(var zip=new ZipArchive(payload,ZipArchiveMode.Read,true)){
    if(zip.Entries.Count>5000)throw new InvalidDataException("Too many files");foreach(var e in zip.Entries){string rel=e.FullName.Replace('/','\\');if(rel.StartsWith("LifeAC-Lighting\\",StringComparison.Ordinal))rel=rel.Substring(16);if(rel.Length==0)continue;
     if(Path.IsPathRooted(rel)||rel.IndexOf(':')>=0||(e.ExternalAttributes&0x400)!=0||((e.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Unsafe archive entry");string dest=Path.GetFullPath(Path.Combine(stage,rel));if(!Within(dest,stage))throw new InvalidDataException("Archive path outside installation");
     if(!ShouldInstall(rel,installHost))continue;total+=e.Length;if(total>600000000||e.Length>300000000)throw new InvalidDataException("Archive size limit");if(rel.EndsWith("\\")){Directory.CreateDirectory(dest);continue;}Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=e.Open())using(var output=new FileStream(dest,FileMode.CreateNew)){byte[] buffer=new byte[65536];long read=0;int n;while((n=input.Read(buffer,0,buffer.Length))>0){read+=n;if(read>e.Length)throw new InvalidDataException("Archive length mismatch");output.Write(buffer,0,n);}if(read!=e.Length)throw new InvalidDataException("Incomplete file");}
    }
   }
   foreach(string required in (installHost?new[]{"LifeAC Lighting.exe","LifeAC Lighting Updater.exe","runtime\\node.exe","src\\server.mjs","web\\index.html","bin\\LifeAC-FrameWorker.exe"}:new[]{"LifeAC Lighting.exe","LifeAC Lighting Updater.exe","desktop\\main.mjs","desktop-runtime\\electron.exe"}))if(!File.Exists(Path.Combine(stage,required)))throw new InvalidDataException("Incomplete application package");
   if(!installHost)File.WriteAllText(Path.Combine(stage,"client-only.flag"),"Client installation: USB/MIDI host components excluded.");Directory.CreateDirectory(Path.GetDirectoryName(target));Directory.Move(stage,target);status("Creating your shortcuts…");string exe=Path.Combine(target,"LifeAC Lighting.exe"),updater=Path.Combine(target,"LifeAC Lighting Updater.exe");
   dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Programs),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)}){Shortcut(shell,Path.Combine(folder,"LifeAC Lighting.lnk"),exe,"",target);Shortcut(shell,Path.Combine(folder,"Update LifeAC Lighting.lnk"),updater,"",target);}
   File.WriteAllBytes(Path.Combine(Data,"update-access.bin"),ProtectedData.Protect(Encoding.UTF8.GetBytes(ReadResource("LifeAC.ReadOnlyAccess")),null,DataProtectionScope.CurrentUser));
   string metadata=Path.Combine(Data,"install.json"),tmp=metadata+".new";File.WriteAllText(tmp,Json.Serialize(new{version=version,directory=target,role=installHost?"host":"client"}));if(File.Exists(metadata))File.Replace(tmp,metadata,metadata+".previous",true);else File.Move(tmp,metadata);
   try{var startup=Json.Deserialize<System.Collections.Generic.Dictionary<string,bool>>(File.ReadAllText(Path.Combine(Data,"startup.json")));if(startup["enabled"])using(var run=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))run.SetValue("LifeAC Lighting","\""+exe+"\" --autostart");}catch{}using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\LifeAC-Lighting")){key.SetValue("DisplayName","LifeAC Lighting");key.SetValue("DisplayVersion",version);key.SetValue("Publisher","Life Anglican Church");key.SetValue("InstallLocation",target);key.SetValue("DisplayIcon",exe);key.SetValue("UninstallString","\""+updater+"\" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}
   if(!installHost&&hostRole.HasValue){PruneOldReleases(target);string vendor=Path.GetFullPath(Path.Combine(Data,"vendor"));if(!Within(vendor,Data))throw new InvalidOperationException("Runtime cleanup target rejected");if(Directory.Exists(vendor)){CheckTree(vendor);Directory.Delete(vendor,true);}}else if(installHost)RequestFirewall(updater,false,status);
   return exe;
  }finally{if(Directory.Exists(stage)&&Within(stage,Root)&&Path.GetDirectoryName(stage).Equals(Root,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(stage).StartsWith("staging-"))Directory.Delete(stage,true);}
 }
 static void Shortcut(dynamic shell,string path,string exe,string arguments,string working){dynamic link=shell.CreateShortcut(path);link.TargetPath=exe;link.Arguments=arguments;link.WorkingDirectory=working;link.IconLocation=exe;link.Save();}
 public static string CurrentVersion(){try{var d=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(Data,"install.json")));return d["version"];}catch{return null;}}
 public static string SavedRole(string data){try{string role=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(data,"role.json")))["role"];if(role=="primary"||role=="backup"||role=="controller")return role;}catch{}try{var info=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(data,"install.json")));return info["role"]=="host"?"primary":"controller";}catch{return "controller";}}
 public static string InstalledExecutable(string root,string data){try{var info=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(data,"install.json")));string dir=Path.GetFullPath(info["directory"]);if(!Within(dir,Path.Combine(root,"releases")))return null;foreach(string required in new[]{"LifeAC Lighting.exe","desktop\\main.mjs","desktop-runtime\\electron.exe"})if(!File.Exists(Path.Combine(dir,required)))return null;if(SavedRole(data)!="controller")foreach(string required in new[]{"runtime\\node.exe","src\\server.mjs","bin\\LifeAC-FrameWorker.exe"})if(!File.Exists(Path.Combine(dir,required)))return null;return Path.Combine(dir,"LifeAC Lighting.exe");}catch{return null;}}
 public static bool IsInstalled(){return InstalledExecutable(Root,Data)!=null;}
 public static void CopyBootstrap(string source,string appExe,string root){string dir=Path.GetDirectoryName(Path.GetFullPath(appExe));if(!Within(dir,Path.Combine(root,"releases"))||Path.GetFileName(appExe)!="LifeAC Lighting.exe"||!File.Exists(appExe))throw new InvalidOperationException("Updater destination rejected");string target=Path.Combine(dir,"LifeAC Lighting Updater.exe");if(!Path.GetFullPath(source).Equals(Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))File.Copy(source,target,true);}
 static void SaveRole(string role){if(role==null)return;File.WriteAllText(Path.Combine(Data,"role.json"),Json.Serialize(new{role=role}));if(role!="controller")File.WriteAllText(Path.Combine(Data,"client.json"),Json.Serialize(new{server=(string)null}));}
 static HttpWebRequest Request(string url,bool binary,bool authenticated){var uri=new Uri(url);if(uri.Scheme!="https")throw new InvalidOperationException("HTTPS required");var r=(HttpWebRequest)WebRequest.Create(uri);r.UserAgent="LifeAC-Lighting-Updater";r.Accept=binary?"application/octet-stream":"application/vnd.github+json";r.AllowAutoRedirect=false;r.Timeout=30000;r.ReadWriteTimeout=120000;if(authenticated){if(uri.Host!="api.github.com")throw new InvalidOperationException("Credential destination rejected");r.Headers["Authorization"]="Bearer "+Token();r.Headers["X-GitHub-Api-Version"]="2022-11-28";}return r;}
 public static object GetJson(string url){using(var response=(HttpWebResponse)Request(url,false,true).GetResponse())using(var r=new StreamReader(response.GetResponseStream()))return Json.DeserializeObject(r.ReadToEnd());}
 public static byte[] Asset(string url,Action<string> status){for(int hop=0;hop<5;hop++){var uri=new Uri(url);bool api=uri.Host=="api.github.com";if(!api&&uri.Host!="release-assets.githubusercontent.com"&&uri.Host!="objects.githubusercontent.com"&&!uri.Host.EndsWith(".githubusercontent.com",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Download host rejected");using(var response=(HttpWebResponse)Request(url,true,api).GetResponse()){
   if((int)response.StatusCode>=300&&(int)response.StatusCode<400){url=response.Headers["Location"];continue;}using(var input=response.GetResponseStream())using(var data=new MemoryStream()){byte[] buffer=new byte[65536];int n;long next=0;while((n=input.Read(buffer,0,buffer.Length))>0){if(data.Length+n>500000000)throw new InvalidDataException("Download too large");data.Write(buffer,0,n);if(data.Length>=next){status("Downloading update: "+data.Length/1000000+" MB");next=data.Length+5000000;}}return data.ToArray();}
  }}throw new InvalidOperationException("Too many download redirects");}
 public static string DownloadAndInstall(Action<string> status,bool verifyOnly=false,string role=null){
  if(!verifyOnly&&HostRunning())throw new InvalidOperationException("Close LifeAC Lighting from its tray menu before updating. Your show data is preserved.");ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
  if(role!=null&&role!="primary"&&role!="backup"&&role!="controller")throw new InvalidOperationException("Choose Primary, Backup or Network Controller.");if(!verifyOnly&&role==null&&!IsInstalled())throw new InvalidOperationException("Reopen the updater and choose this PC's role to install LifeAC Lighting.");
  status("Checking the latest LifeAC Lighting release…");var release=(System.Collections.Generic.Dictionary<string,object>)GetJson("https://api.github.com/repos/"+Repo+"/releases/latest");var assets=(System.Collections.IEnumerable)release["assets"];System.Collections.Generic.Dictionary<string,object> manifestAsset=null,package=null;
  foreach(var item in assets){var a=(System.Collections.Generic.Dictionary<string,object>)item;if(Convert.ToString(a["name"])=="update-manifest.json")manifestAsset=a;if(Convert.ToString(a["name"])=="LifeAC-Lighting-win-x64.zip")package=a;}if(manifestAsset==null||package==null)throw new InvalidDataException("Release assets incomplete");
  var manifest=Json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(Encoding.UTF8.GetString(Asset(Convert.ToString(manifestAsset["url"]),status)));string version=manifest["version"];System.Version parsed;if(!System.Version.TryParse(version,out parsed)||Convert.ToString(release["tag_name"])!="v"+version||manifest["package"]!="LifeAC-Lighting-win-x64.zip")throw new InvalidDataException("Release metadata mismatch");
  if(!verifyOnly&&role==null&&IsInstalled()&&CurrentVersion()==version){string existing=InstalledExecutable(Root,Data);CopyBootstrap(Assembly.GetExecutingAssembly().Location,existing,Root);File.WriteAllBytes(Path.Combine(Data,"update-access.bin"),ProtectedData.Protect(Encoding.UTF8.GetBytes(Token()),null,DataProtectionScope.CurrentUser));status("LifeAC Lighting "+version+" is current. The lightweight updater is ready.");return existing;}byte[] bytes=Asset(Convert.ToString(package["url"]),status);using(var data=new MemoryStream(bytes)){if(Sha(data)!=manifest["sha256"].ToLowerInvariant())throw new InvalidDataException("Update checksum mismatch — nothing installed");if(verifyOnly)return "Verified private GitHub release "+version+"; package checksum matched. No installation performed.";data.Position=0;string exe=Install(data,version,status,role==null?(bool?)null:role!="controller");SaveRole(role);CopyBootstrap(Assembly.GetExecutingAssembly().Location,exe,Root);return exe;}
 }
 public static void RemoveInstallation(){
  if(HostRunning())throw new InvalidOperationException("Close LifeAC Lighting first");string full=Path.GetFullPath(Root),expected=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","LifeAC-Lighting"));if(full!=expected||!full.EndsWith("\\Programs\\LifeAC-Lighting",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Uninstall target rejected");
  string data=Path.GetFullPath(Data),expectedData=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LifeAC-Lighting"));if(data!=expectedData||data==full)throw new InvalidOperationException("Uninstall data target rejected");if(Directory.Exists(full))CheckTree(full);if(Directory.Exists(data))CheckTree(data);
  if(!RequestFirewall(Assembly.GetExecutingAssembly().Location,true,s=>{}))throw new InvalidOperationException("LAN firewall cleanup requires Windows approval. Run uninstall again and approve the Windows prompt.");
  RemoveAppDirectories(full,data,expected,expectedData);string legacy=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"lifeac-lighting-desktop");if(Directory.Exists(legacy)){CheckTree(legacy);Directory.Delete(legacy,true);}foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Programs),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)})foreach(string name in new[]{"LifeAC Lighting.lnk","Update LifeAC Lighting.lnk"}){string file=Path.Combine(folder,name);if(File.Exists(file))File.Delete(file);}
  using(var run=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){if(run!=null)run.DeleteValue("LifeAC Lighting",false);}
  Registry.CurrentUser.DeleteSubKeyTree(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\LifeAC-Lighting",false);
 }
 static void CheckTree(string dir){if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Uninstall found a redirected folder; manual review required");foreach(string child in Directory.GetDirectories(dir))CheckTree(child);}
 public static void RemoveAppDirectories(string root,string data,string expectedRoot,string expectedData){root=Path.GetFullPath(root);data=Path.GetFullPath(data);if(!root.Equals(Path.GetFullPath(expectedRoot),StringComparison.OrdinalIgnoreCase)||!data.Equals(Path.GetFullPath(expectedData),StringComparison.OrdinalIgnoreCase)||root.Equals(data,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Cleanup target rejected");if(Directory.Exists(root))CheckTree(root);if(Directory.Exists(data))CheckTree(data);if(Directory.Exists(root))Directory.Delete(root,true);if(Directory.Exists(data))Directory.Delete(data,true);}
 public static void PruneOldReleases(string keep){PruneReleases(Root,keep);} public static void PruneReleases(string root,string keep){string releases=Path.Combine(root,"releases");if(!Within(keep,releases))throw new InvalidOperationException("Release cleanup target rejected");CheckTree(root);foreach(var dir in Directory.GetDirectories(releases)){if(Path.GetFullPath(dir).Equals(Path.GetFullPath(keep),StringComparison.OrdinalIgnoreCase))continue;if(!Within(dir,releases))throw new InvalidOperationException("Release cleanup target rejected");Directory.Delete(dir,true);}}
 static int Netsh(string args){using(var p=Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"netsh.exe"),"advfirewall firewall "+args){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true})){p.OutputDataReceived+=(s,e)=>{};p.ErrorDataReceived+=(s,e)=>{};p.BeginOutputReadLine();p.BeginErrorReadLine();if(!p.WaitForExit(15000)){p.Kill();return -1;}return p.ExitCode;}}
 public static bool ConfigureFirewall(bool remove){foreach(var type in new[]{"TCP","UDP"}){string name="LifeAC Lighting LAN "+type;Netsh("delete rule name=\""+name+"\"");if(!remove&&Netsh("add rule name=\""+name+"\" dir=in action=allow protocol="+type+" localport="+(type=="TCP"?"47832":"47833")+" profile=any remoteip=any program=\""+Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","node.exe")+"\"")!=0)return false;}return true;}
 public static bool RequestFirewall(string exe,bool remove,Action<string> status){try{status("Requesting Windows approval for lighting LAN / VPN access…");using(var p=Process.Start(new ProcessStartInfo(exe,remove?"--remove-firewall":"--configure-firewall"){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden})){p.WaitForExit();return p.ExitCode==0;}}catch{status("LAN access needs Windows firewall approval. Local lighting still works.");return false;}}
 public static void CleanupUninstaller(){string exe=Path.GetFullPath(Assembly.GetExecutingAssembly().Location),temp=Path.GetFullPath(Path.GetTempPath()).TrimEnd('\\');if(!Path.GetDirectoryName(exe).Equals(temp,StringComparison.OrdinalIgnoreCase)||!(Path.GetFileName(exe).StartsWith("LifeAC-Uninstall-",StringComparison.Ordinal)||Path.GetFileName(exe).StartsWith("LifeAC-Updater-",StringComparison.Ordinal)))return;string code="Wait-Process -Id "+Process.GetCurrentProcess().Id+" -ErrorAction SilentlyContinue; Remove-Item -LiteralPath '"+exe.Replace("'","''")+"' -Force -ErrorAction SilentlyContinue";Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(code))){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
